def punnett2(rng, mc):
    crosses = [('Aa × Aa', 'แสดงลักษณะด้อย', Fr(1, 4), 'AA : Aa : aa = 1 : 2 : 1 → aa = 1/4'),
               ('Aa × Aa', 'แสดงลักษณะเด่น', Fr(3, 4), 'AA + Aa = 3/4'), ('Aa × aa', 'แสดงลักษณะด้อย', Fr(1, 2), 'Aa : aa = 1 : 1'),
               ('AaBb × AaBb', 'แสดงลักษณะเด่นทั้งสองลักษณะ', Fr(9, 16), '3/4 × 3/4 = 9/16'),
               ('AaBb × AaBb', 'แสดงลักษณะด้อยทั้งสองลักษณะ', Fr(1, 16), '1/4 × 1/4 = 1/16'),
               ('AaBb × aabb', 'มีจีโนไทป์ aabb', Fr(1, 4), '1/2 × 1/2 = 1/4'),
               ('AaBb × AaBb', 'มีจีโนไทป์ AaBb', Fr(1, 4), '1/2 × 1/2 = 1/4'),
               ('AaBb × AaBb', 'เด่นลักษณะ A แต่ด้อยลักษณะ b', Fr(3, 16), '3/4 × 1/4 = 3/16'),
               ('X<sup>H</sup>X<sup>h</sup> × X<sup>H</sup>Y', 'เป็นลูกชายที่เป็นโรคฮีโมฟีเลีย (เทียบกับลูกทั้งหมด)', Fr(1, 4), 'ลูก: X<sup>H</sup>X<sup>H</sup>, X<sup>H</sup>X<sup>h</sup>, X<sup>H</sup>Y, X<sup>h</sup>Y → X<sup>h</sup>Y = 1/4'),
               ('I<sup>A</sup>i × I<sup>B</sup>i', 'มีหมู่เลือด O', Fr(1, 4), 'ลูก: I<sup>A</sup>I<sup>B</sup>, I<sup>A</sup>i, I<sup>B</sup>i, ii → ii = 1/4'),
               ('I<sup>A</sup>i × I<sup>B</sup>i', 'มีหมู่เลือด AB', Fr(1, 4), 'I<sup>A</sup>I<sup>B</sup> = 1/4'),
               ('Rr × Rr (ข่มไม่สมบูรณ์: RR แดง, Rr ชมพู, rr ขาว)', 'มีดอกสีชมพู', Fr(1, 2), 'RR : Rr : rr = 1 : 2 : 1 → Rr = 1/2')]
    c, d, p, s = rng.choice(crosses)
    pool = [Fr(1, 4), Fr(3, 4), Fr(1, 2), Fr(9, 16), Fr(3, 16), Fr(1, 16), Fr(1, 8), Fr(1), Fr(0)]
    return mc(f'ผสม {c} ความน่าจะเป็นที่ลูก{d}เท่ากับเท่าใด (ยีนแต่ละคู่อยู่อิสระต่อกัน)', fr(p), [fr(x) for x in pool if x != p],
              ol('เขียนตารางพันเนตต์หรือคิดทีละยีนแล้วคูณกัน', s))


def gametes(rng, mc):
    g = rng.choice(['AaBb', 'AaBbCc', 'AABbCc', 'AaBbCcDd', 'aaBbCC', 'AaBBccDd'])
    het = sum(1 for i in range(0, len(g), 2) if g[i] != g[i + 1])
    return NUM(f'สิ่งมีชีวิตจีโนไทป์ {g} (ยีนอยู่อิสระต่อกัน) สร้างเซลล์สืบพันธุ์ได้กี่แบบ', 2 ** het,
               ol(f'นับคู่ยีนที่เป็นเฮเทอโรไซกัส = {het} คู่', f'จำนวนแบบ = 2<sup>{het}</sup> = {2**het}'), h='จำนวนแบบ = 2ⁿ เมื่อ n = คู่ยีนที่เป็นเฮเทอโรไซกัส')


def complement(rng, mc):
    seq = ''.join(rng.choice('ATGC') for _ in range(6))
    comp = seq.translate(str.maketrans('ATGC', 'TACG'))
    rna = seq.translate(str.maketrans('ATGC', 'UACG'))
    if rng.random() < .5:
        return mc(f'สายดีเอ็นเอ 5′-{seq}-3′ มีสายคู่สม (อ่าน 3′→5′) เป็นอย่างไร', comp, [seq, rna, comp[::-1], seq.translate(str.maketrans('ATGC', 'GCAT'))],
                  ol('A คู่กับ T และ G คู่กับ C', f'{seq} → {comp}'))
    return mc(f'ถ้าดีเอ็นเอสายแม่แบบคือ 3′-{seq}-5′ mRNA ที่ถอดรหัสได้ (อ่าน 5′→3′) คือข้อใด', rna, [comp, seq, rna[::-1], seq.translate(str.maketrans('ATGC', 'GCAU'))],
              ol('mRNA จับคู่กับสายแม่แบบ: A→U, T→A, G→C, C→G', f'{seq} → {rna}'))


